using System;using System.Linq;using System.IO;using System.Drawing;using System.Reflection;using System.Collections.Generic;using System.Windows.Forms;
class KitchenLearningChecks{
static BindingFlags F=BindingFlags.NonPublic|BindingFlags.Instance;static object Call(Game g,string n,params object[] a){return typeof(Game).GetMethod(n,F).Invoke(g,a);}static IEnumerable<Control> All(Control c){foreach(Control x in c.Controls){yield return x;foreach(var y in All(x))yield return y;}}static void Check(bool b,string m){if(!b)throw new Exception(m);}static void Snap(Form d,string name){using(var image=new Bitmap(d.Width,d.Height)){d.DrawToBitmap(image,d.ClientRectangle);image.Save(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,name+".png"));}}
[STAThread]static void Main(){try{Run();}catch(Exception e){while(e.InnerException!=null)e=e.InnerException;Console.WriteLine("FAIL: "+e.GetType().Name+": "+e.Message+"\n"+e.StackTrace);Environment.ExitCode=1;}}static void Run(){Application.SetUnhandledExceptionMode(UnhandledExceptionMode.ThrowException);Application.EnableVisualStyles();using(var game=new Game()){game.Show();game.Opacity=0;game.Size=new Size(980,760);var save=new Save();typeof(Game).GetField("save",F).SetValue(game,save);Call(game,"PrepareKitchenWords","cut");var state=(KitchenWorkState)Call(game,"KitchenState");state.boardLoaded=true;state.cut=0;var bank=(List<RogueEntry>)Call(game,"KitchenBank");var entry=state.cutWords[0];var others=bank.Where(w=>w.word!=entry.word&&ExpeditionVocabulary.Meaning(w)!=ExpeditionVocabulary.Meaning(entry)).Take(3).ToList();var questions=new[]{new RogueQuestion{entry=entry,kind=0,answer=0,options=new List<string>{ExpeditionVocabulary.Meaning(entry),ExpeditionVocabulary.Meaning(others[0]),ExpeditionVocabulary.Meaning(others[1]),ExpeditionVocabulary.Meaning(others[2])}},new RogueQuestion{entry=entry,kind=1,answer=0,options=new List<string>{entry.word,others[0].word,others[1].word,others[2].word}},new RogueQuestion{entry=entry,kind=3,answer=-1,options=new List<string>()}};for(int i=0;i<3;i++)state.cutWords[i]=entry;state.SetQuestion("cut",questions[0]);var pending=Engine.Json.Deserialize<Save>(Engine.Json.Serialize(save));Check(pending.kitchenWork.cutQuestion.entry.word==entry.word&&pending.kitchenWork.cutQuestion.options.Count==4,"pending kitchen question not saved");Exception failure=null;int phase=0;int sceneTop=-1;var timer=new Timer{Interval=450};timer.Tick+=(s,e)=>{var d=Application.OpenForms.Cast<Form>().FirstOrDefault(x=>x!=game);if(d==null)return;try{var icons=All(d).OfType<RogueIcon>().ToList();var hear=icons.Single(x=>x.Kind=="speaker");var star=icons.Single(x=>x.Kind=="star");var input=All(d).OfType<TextBox>().Single();var scene=All(d).OfType<KitchenProcessView>().Single();if(sceneTop<0)sceneTop=scene.Top;Check(scene.Top==sceneTop,"animation moved between question types");var buttons=All(d).OfType<VNButton>().ToList();if(phase==0){Check(hear.Visible&&star.Visible&&!input.Visible,"meaning-choice controls wrong");var prompt=All(d).OfType<KitchenWordPrompt>().Single();Check(Math.Abs((hear.Top+hear.Height/2)-(prompt.Top+prompt.Height/2))<=1,"icons not vertically centered");star.PerformClick();Check(save.words.Any(w=>w.text==entry.word),"favorite wrong word");Snap(d,"kitchen-meaning-choice");buttons.Single(b=>b.Text.StartsWith("B. ")).PerformClick();Check(state.cut==0,"wrong choice advanced cooking");buttons.Single(b=>b.Text.StartsWith("A. ")).PerformClick();Check(state.cut==1&&!hear.Enabled,"correct choice/animation wrong");state.SetQuestion("cut",questions[1]);phase=1;}else if(phase==1&&star.Enabled){Check(!hear.Visible&&star.Visible&&!input.Visible,"Chinese-to-English leaked pronunciation");Check(star.Selected,"favorite did not persist");Snap(d,"kitchen-english-choice");buttons.Single(b=>b.Text.StartsWith("A. ")).PerformClick();state.SetQuestion("cut",questions[2]);phase=2;}else if(phase==2&&star.Enabled){Check(hear.Visible&&input.Visible,"spelling controls wrong");input.Text=entry.word;Snap(d,"kitchen-spelling");buttons.Single(b=>b.Text.StartsWith("确认拼写")).PerformClick();phase=3;}else if(phase==3&&buttons.Any(b=>b.Text.StartsWith("拿取")&&b.Enabled)){Check(state.cut==3&&!hear.Visible&&!star.Visible,"completion controls wrong");var progress=ExpeditionVocabulary.Profile(save.rogue).words[entry.word];Check(progress.stage==1&&progress.streak==3,"kitchen did not update shared learning");var summary=(string)Call(game,"VocabularyProgressText","四六级混合");Check(summary.StartsWith("已学会 1 /"),"shared progress summary wrong");var roundtrip=Engine.Json.Deserialize<Save>(Engine.Json.Serialize(save));Check(roundtrip.rogue.expeditionLearning.words[entry.word].stage==1,"shared progress not saved");Check(roundtrip.kitchenWork.cutQuestion==null,"answered kitchen question saved");Snap(d,"kitchen-learning-finished");phase=4;timer.Stop();d.Close();}}catch(Exception ex){Console.WriteLine("CHECK FAILURE: "+ex.GetType().Name+": "+ex.Message);failure=ex;timer.Stop();d.Close();}};timer.Start();Call(game,"ShowKitchenProcess","cut");timer.Dispose();if(failure!=null)throw failure;Check(phase==4,"three question types did not complete");game.Size=new Size(800,500);state.cut=0;state.boardLoaded=true;state.SetQuestion("cut",questions[1]);var closer=new Timer{Interval=500};closer.Tick+=(s,e)=>{foreach(Form d in Application.OpenForms.Cast<Form>().ToArray())if(d!=game){Snap(d,"kitchen-learning-small");closer.Stop();d.Close();}};closer.Start();Call(game,"ShowKitchenProcess","cut");closer.Dispose();TavernTime.State(save).phase=StoryTime.Night;Call(game,"ShowKitchenWork");Application.DoEvents();var kitchen=All(game).OfType<KitchenRoomView>().Single();Check(kitchen.WordProgress.StartsWith("已学会 1 /"),"kitchen progress display stale");Snap(game,"kitchen-shared-progress");var panel=new WoodlandEntryPanel(false,"探索十个地点，在岔路间选择路线。","四六级混合",mode=>{},()=>{},()=>{},()=>{},mode=>(string)Call(game,"VocabularyProgressText",mode)){Size=new Size(620,440)};using(var image=new Bitmap(panel.Width,panel.Height)){panel.DrawToBitmap(image,panel.ClientRectangle);image.Save(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"expedition-shared-progress.png"));}panel.Dispose();game.Close();}Console.WriteLine("PASS: all kitchen question types, wrong-answer retry, icon alignment, answer privacy, favorite persistence, shared mastery and save roundtrip.");}}
